abstract class Light(var on: Boolean) {
    fun flip() {
        on = !on
    }

    abstract fun glow(): String
}

class Lamp : Light(false) {
    override fun glow(): String {
        if (on) {
            return "bright"
        } else {
            return "dark"
        }
    }
}

fun main() {
    val lamp = Lamp()
    println(lamp.glow())
    lamp.flip()
    println(lamp.glow())
    lamp.flip()
    println(lamp.glow())
}
